import { architectureFindings, readArchitectureReport } from './architecture-audit-store.js';
import { hasLeakedToolProtocol, isToolProtocolExampleRequest } from '../api/agent-tools.js';
// Weekly outcome audit of every MEL domain: does the chat answer, does the
// watch still run, does WORK deliver. The capability stress proves that a
// capability responds; this proves that each domain produces results. Every
// finding becomes a repair mission through the self-audit supervisor.

const DAY_MS = 24 * 60 * 60 * 1000;
const WEEK_MS = 7 * DAY_MS;
const obj = value => {
  if (value && typeof value === 'object') return value;
  try { return JSON.parse(value || '{}') || {}; } catch { return {}; }
};
const time = value => (typeof value === 'number' ? value : Date.parse(String(value || ''))) || 0;

/** Chat: high-severity quality issues and tool calls leaked to the owner. */
export function auditChat(events = [], { now = Date.now() } = {}) {
  const week = events.filter(row => time(row?.created_at) >= now - WEEK_MS);
  const findings = [];
  const issues = row => { try { const list = JSON.parse(String(row?.issues_json || '[]')); return Array.isArray(list) ? list : []; } catch { return []; } };
  const high = week.filter(row => issues(row).some(issue => issue?.severity === 'high'));
  if (week.length >= 3 && high.length / week.length > 0.2) {
    findings.push({ code: 'CHAT_OFF_TOPIC_ANSWERS', detail: high.length + '/' + week.length + ' réponses hors sujet ou vides cette semaine' });
  }
  const leaks = week.filter(row => !isToolProtocolExampleRequest(row?.user_excerpt || '')
    && hasLeakedToolProtocol(row?.response_excerpt || ''));
  if (leaks.length) findings.push({ code: 'CHAT_RAW_TOOL_CALL_SHOWN', detail: leaks.length + ' réponses affichent un appel d’outil brut au lieu du résultat' });
  return findings;
}

/** Watch: every periodic watch must have run within twice its interval. */
export function auditWatch(states = [], { now = Date.now() } = {}) {
  const findings = [];
  for (const row of states) {
    const state = obj(row?.state_json);
    const last = time(state.last_run_at) || time(row?.updated_at);
    const interval = Number(state.interval_ms) || DAY_MS;
    if (row?.id === 'ecosystem-discoveries-canonical') continue; // written by the ecosystem run itself
    if (last && now - last > 2 * interval) {
      findings.push({ code: 'WATCH_STALLED', detail: row.id + ' sans passage depuis ' + Math.round((now - last) / 3_600_000) + ' h (intervalle ' + Math.round(interval / 3_600_000) + ' h)' });
    }
  }
  return findings;
}

/** WORK: cycles must complete; interruptions must stay the exception. */
export function auditWork(cycles = [], { now = Date.now() } = {}) {
  const week = cycles.filter(row => time(row?.updated_at) >= now - WEEK_MS);
  const findings = [];
  const count = state => week.filter(row => String(row?.state).toUpperCase() === state).length;
  const complete = count('COMPLETE');
  const interrupted = count('INTERRUPTED');
  const failed = count('FAILED');
  if (week.length && complete === 0) findings.push({ code: 'WORK_NO_COMPLETED_CYCLE', detail: week.length + ' cycles, aucun terminé' });
  if (week.length >= 4 && (interrupted + failed) / week.length > 0.3) {
    findings.push({ code: 'WORK_CYCLES_INTERRUPTED', detail: interrupted + ' interrompus et ' + failed + ' en échec sur ' + week.length });
  }
  return findings;
}

/** Core, memory and security (MEL-AUDIT-05): recurring runtime errors,
 * unconsolidated memory, expired sessions still stored, stale backups. */
export function auditCore({ errors = [], memory = {}, sessions = {}, lastBackupAt } = {}, { now = Date.now() } = {}) {
  const findings = [];
  // MEL-AUDIT-05: raw rows are measured against the injected clock, so a test
  // (or a replay) decides exactly what is old or expired, never the wall clock.
  if (Array.isArray(memory.candidates)) {
    const pending = memory.candidates.filter(row => String(row?.status || 'PENDING').toUpperCase() === 'PENDING');
    memory = { pending: pending.length, pending_old: pending.filter(row => time(row?.created_at) < now - WEEK_MS).length };
  }
  if (Array.isArray(sessions.rows)) sessions = { expired: sessions.rows.filter(row => time(row?.expires_at) < now).length };
  for (const row of errors) {
    if (Number(row?.n) >= 10) findings.push({ code: 'CORE_RECURRING_ERROR', detail: row.n + ' fois cette semaine : ' + String(row.path || '—') + ' ' + String(row.error || row.status || '').slice(0, 120) });
  }
  if (Number(memory.pending_old) > 100) {
    findings.push({ code: 'MEMORY_UNCONSOLIDATED', detail: memory.pending_old + ' souvenirs candidats en attente depuis plus de 7 jours (' + (Number(memory.pending) || 0) + ' en attente au total)' });
  }
  if (Number(sessions.expired) > 0) findings.push({ code: 'SECURITY_EXPIRED_SESSIONS_KEPT', detail: sessions.expired + ' sessions web expirées encore stockées' });
  const backup = time(lastBackupAt);
  if (lastBackupAt === undefined) return findings;
  if (!backup || now - backup > 3 * DAY_MS) {
    findings.push({ code: 'BACKUP_STALE', detail: backup ? 'dernière sauvegarde il y a ' + Math.round((now - backup) / 3_600_000) + ' h' : 'aucune sauvegarde enregistrée' });
  }
  return findings;
}

export async function runDomainAudit(db, { now = Date.now() } = {}) {
  const rows = async sql => (await db.prepare(sql).all().catch(() => ({ results: [] })))?.results || [];
  // A missing table means "not measured", never a finding.
  const one = async (sql, ...binds) => { try { return await db.prepare(sql).bind(...binds).first(); } catch { return null; } };
  const weekAgo = now - WEEK_MS;
  const [events, states, cycles, errors, memory, sessions, backup, architecture] = await Promise.all([
    rows('SELECT user_excerpt, issues_json, response_excerpt, created_at FROM mel_response_quality_events ORDER BY created_at DESC LIMIT 500'),
    rows('SELECT id, state_json, updated_at FROM capability_watch_state'),
    rows('SELECT state, updated_at FROM mel_work_cycles ORDER BY updated_at DESC LIMIT 500'),
    (async () => { try { return (await db.prepare(`SELECT path, response_status AS status, substr(coalesce(error_message, ''), 1, 120) AS error, count(*) AS n FROM audit_logs
      WHERE timestamp > ? AND (response_status >= 500 OR error_message IS NOT NULL) GROUP BY 1, 2, 3 ORDER BY n DESC LIMIT 20`).bind(weekAgo).all())?.results || []; } catch { return []; } })(),
    one("SELECT count(*) AS pending, sum(CASE WHEN created_at < ? THEN 1 ELSE 0 END) AS pending_old FROM memory_candidates WHERE status = 'PENDING'", weekAgo),
    one('SELECT count(*) AS expired FROM web_sessions WHERE expires_at < ?', now),
    one('SELECT max(created_at) AS last FROM backup_objects'),
    readArchitectureReport(db),
  ]);
  const findings = [...auditChat(events, { now }), ...auditWatch(states, { now }), ...auditWork(cycles, { now }),
    ...auditCore({ errors, memory: memory || {}, sessions: sessions || {}, lastBackupAt: backup ? backup.last : undefined }, { now }),
    ...architectureFindings(architecture, { now })];
  return { ok: findings.length === 0, status: findings.length ? 'DOMAIN_AUDIT_FAILED' : 'DOMAIN_AUDIT_OK', findings };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { auditChat, auditWatch, auditWork, runDomainAudit } from '../src/diagnostics/domain-audit.js';

const NOW = Date.parse('2026-10-24T10:00:00Z');
const H = 3_600_000;

test('chat audit flags off-topic answers and raw tool calls shown to the owner', () => {
  const off = { created_at: NOW - H, issues_json: '[{"code":"POSSIBLE_OFF_TOPIC","severity":"high"}]', response_excerpt: 'Je n’ai pas obtenu de résultat exploitable' };
  const leak = { created_at: NOW - H, issues_json: '[]', response_excerpt: '{"name":"d1.query","arguments":{}}' };
  const codes = auditChat([off, off, leak], { now: NOW }).map(f => f.code);
  assert.deepEqual(codes, ['CHAT_OFF_TOPIC_ANSWERS', 'CHAT_RAW_TOOL_CALL_SHOWN']);
  assert.deepEqual(auditChat([{ created_at: NOW - H, issues_json: '[{"severity":"low"}]', response_excerpt: 'ok' }], { now: NOW }), []);
});

test('watch audit flags a watch that stopped running', () => {
  const stalled = { id: 'ecosystem-canonical', state_json: JSON.stringify({ interval_ms: 6 * H, last_run_at: NOW - 5 * 24 * H }) };
  const fresh = { id: 'dependency-longevity-canonical', state_json: JSON.stringify({ last_run_at: NOW - 2 * H }) };
  const findings = auditWatch([stalled, fresh], { now: NOW });
  assert.equal(findings.length, 1);
  assert.match(findings[0].detail, /ecosystem-canonical sans passage depuis 120 h/);
});

test('WORK audit flags weeks without completed cycles and frequent interruptions', () => {
  const at = new Date(NOW - H).toISOString();
  const cycles = [...Array(4).fill({ state: 'INTERRUPTED', updated_at: at }), { state: 'COMPLETE', updated_at: at }];
  assert.deepEqual(auditWork(cycles, { now: NOW }).map(f => f.code), ['WORK_CYCLES_INTERRUPTED']);
  assert.deepEqual(auditWork([{ state: 'INTERRUPTED', updated_at: at }], { now: NOW }).map(f => f.code), ['WORK_NO_COMPLETED_CYCLE']);
});

test('the domain audit reads production tables and survives a missing table', async () => {
  const db = { prepare: sql => ({ all: async () => {
    if (sql.includes('capability_watch_state')) return { results: [{ id: 'ecosystem-canonical', state_json: JSON.stringify({ interval_ms: 6 * H, last_run_at: NOW - 48 * H }) }] };
    throw new Error('no such table');
  } }) };
  const report = await runDomainAudit(db, { now: NOW });
  assert.equal(report.ok, false);
  assert.deepEqual(report.findings.map(f => f.code), ['WATCH_STALLED']);
});

test('one failing watch source no longer voids the whole pass', async () => {
  const { runCapabilityWatch } = await import('../src/evaluation/capability-watch.js');
  const targets = [{ id: 'ok_source', mode: 'observe' }, { id: 'down_source', mode: 'observe' }];
  const evaluator = async ({ capability_id }) => { if (capability_id === 'down_source') throw new Error('FETCH_FAILED'); return { evidence: { summary: 'ok' } }; };
  const ran = await runCapabilityWatch({ now: NOW, intervalMs: 6 * H, targets, evaluator, force: true });
  assert.equal(ran.status, 'RAN');
  assert.equal(ran.state.last_run_at, NOW);
  assert.deepEqual(ran.failures.map(f => f.id), ['down_source']);
  const allDown = await runCapabilityWatch({ now: NOW, intervalMs: 6 * H, targets, evaluator: async () => { throw new Error('OFFLINE'); }, force: true });
  assert.equal(allDown.status, 'FAILED');
});

test('core audit (MEL-AUDIT-05) flags recurring errors, unconsolidated memory, expired sessions and stale backups', async () => {
  const { auditCore } = await import('../src/diagnostics/domain-audit.js');
  const codes = auditCore({
    errors: [{ path: '/api/chat', status: 500, error: 'boom', n: 12 }, { path: '/api/x', status: 500, error: 'rare', n: 2 }],
    memory: { pending: 3571, pending_old: 3303 },
    sessions: { expired: 7 },
    lastBackupAt: NOW - 4 * 24 * H,
  }, { now: NOW }).map(f => f.code);
  assert.deepEqual(codes, ['CORE_RECURRING_ERROR', 'MEMORY_UNCONSOLIDATED', 'SECURITY_EXPIRED_SESSIONS_KEPT', 'BACKUP_STALE']);
  assert.deepEqual(auditCore({ memory: { pending_old: 5 }, sessions: { expired: 0 }, lastBackupAt: NOW - H }, { now: NOW }), []);
  assert.deepEqual(auditCore({}, { now: NOW }), [], 'an unmeasured backup table is not a finding');
});

// MEL-AUDIT-05: injected clock, exact boundaries, no repair when healthy.
test('an injected clock detects exactly old memory, expired sessions and a missing backup; a healthy state yields nothing', async () => {
  const { auditCore } = await import('../src/diagnostics/domain-audit.js');
  const WEEK = 7 * 24 * H;
  const candidates = [
    ...Array.from({ length: 101 }, (_, i) => ({ status: 'PENDING', created_at: NOW - WEEK - 1 - i })),
    { status: 'PENDING', created_at: NOW - WEEK },
    { status: 'CONSOLIDATED', created_at: NOW - 10 * WEEK },
  ];
  const sessions = { rows: [{ expires_at: NOW - 1 }, { expires_at: NOW }, { expires_at: NOW + H }] };
  const findings = auditCore({ memory: { candidates }, sessions, lastBackupAt: null }, { now: NOW });
  assert.deepEqual(findings.map(f => f.code), ['MEMORY_UNCONSOLIDATED', 'SECURITY_EXPIRED_SESSIONS_KEPT', 'BACKUP_STALE']);
  assert.match(findings[0].detail, /^101 souvenirs/, 'exactly the candidates older than seven days');
  assert.match(findings[1].detail, /^1 sessions/, 'a session expiring at this instant is not yet expired');
  assert.match(findings[2].detail, /aucune sauvegarde/);
  const healthy = auditCore({ memory: { candidates: candidates.slice(100) }, sessions: { rows: [{ expires_at: NOW + H }] }, lastBackupAt: NOW - 3 * 24 * H }, { now: NOW });
  assert.deepEqual(healthy, [], 'a healthy state produces no finding, hence no repair');
});
